import { Component, OnInit, SecurityContext } from '@angular/core';
import { FormGroup, FormBuilder, Validators } from '@angular/forms';
import { SafeHtml, DomSanitizer } from '@angular/platform-browser';
import { ActivatedRoute, Router } from '@angular/router';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { AngularEditorConfig } from '@kolkov/angular-editor';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { IAddOrUpdateArticleModel, AddOrUpdateArticleModel } from 'src/app/data/model/article/AddOrUpdateArticleModel';
import { IArticleDetailModel } from 'src/app/data/model/article/ArticleDetailModel';
import { IArticleFilterModel, ArticleFilterModel } from 'src/app/data/model/article/ArticleFilterModel';
import { IArticleModel } from 'src/app/data/model/article/ArticleModel';
import { ArticleService } from 'src/app/data/service/article/article.service';

@Component({
  selector: 'app-update-article',
  templateUrl: './update-article.component.html',
  styleUrls: ['./update-article.component.scss']
})
export class UpdateArticleComponent implements OnInit {

  searchTitle = '';

  editorConfig: AngularEditorConfig = {
    editable: true,
    spellcheck: true,
    height: '25rem',
    minHeight: '5rem',
    placeholder: 'توضیحات کوتاه...',
    translate: 'no',
    sanitize: true
  };

  editorConfig2: AngularEditorConfig = {
    editable: true,
    spellcheck: true,
    height: '25rem',
    minHeight: '5rem',
    placeholder: 'توضیحات اصلی...',
    translate: 'no',
    sanitize: true
  };

  selectedArticleId = 0;
  articleSelected = false;
  articleDetail: IArticleDetailModel;
  filteredArticles: IArticleFilterModel;
  shortDescription: string;
  description: SafeHtml;
  imageUrl: any;
  updateArticleForm: FormGroup;
  empty = false;

  article: IAddOrUpdateArticleModel;

  constructor(
    private articleService: ArticleService,
    private fb: FormBuilder,
    public toastController: ToastController,
    public loadingController: LoadingController,
    private activatedRoute: ActivatedRoute,
    private router: Router,
    private domSanitizer: DomSanitizer,
    public alertController: AlertController) { }

  ngOnInit(): void {

    this.updateArticleForm = this.fb.group({
      name: ['', [Validators.required, Validators.minLength(3), Validators.maxLength(200)]],
      imageUrl: ['http://localhost:4300/assets/images/in-progress.webp', [Validators.minLength(0), Validators.maxLength(1000000)]],
      imageNamePNG: ['http://localhost:4300/assets/images/in-progress.png', [Validators.minLength(0), Validators.maxLength(1000000)]],
      shortDescriptionHtmlContent: ['', [Validators.required, Validators.minLength(10), Validators.maxLength(1000000)]],
      descriptionHtmlContent: ['', [Validators.required, Validators.minLength(10), Validators.maxLength(1000000)]]
    });

    let filter: IArticleFilterModel;

    this.activatedRoute.queryParams.subscribe(params => {

      const page = params.page ? params.page : 1;
      const take = params.take ? params.take : 12;
      const title = params.title ? params.title : null;

      filter = new ArticleFilterModel(page, take, title);

      this.filteredArticles = filter;

      SharedIonic.loading(this.loadingController);

      this.articleService.GetSellerArticlesByFilter(filter).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (res.status === GResponse.SuccessStatus) {
            this.filteredArticles = res.data;
          } else {
            this.empty = true;
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    });
  }

  async presentAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onUpdate();
          }
        }
      ]
    });

    await alert.present();
  }

  onUpdate() {

    if (this.updateArticleForm.valid) {

      SharedIonic.loading(this.loadingController);

      // this.shortDescription = this.domSanitizer
      //   .sanitize(SecurityContext.HTML, this.updateArticleForm.value.shortDescriptionHtmlContent);

      this.shortDescription = this.updateArticleForm.value.shortDescriptionHtmlContent;

      this.description = this.domSanitizer
        .sanitize(SecurityContext.HTML, this.updateArticleForm.value.descriptionHtmlContent);

      this.article =
        new AddOrUpdateArticleModel(
          this.selectedArticleId,
          this.updateArticleForm.value.name,
          this.shortDescription,
          this.description,
          this.updateArticleForm.value.imageUrl,
          this.updateArticleForm.value.imageNamePNG
        );

      this.articleService.SellerAddOrUpdateArticle(this.article).subscribe(
        res => {
          if (GResponse.SuccessStatus === res.status) {

            this.filteredArticles = new ArticleFilterModel();

            this.articleService.GetSellerArticlesByFilter(this.filteredArticles).subscribe(
              res => {
                SharedIonic.dismissLoading(this.loadingController);
                if (res.status === GResponse.SuccessStatus) {
                  this.filteredArticles = res.data;
                  this.articleSelected = false;
                  SharedIonic.successToast(this.toastController);
                } else {
                  SharedIonic.unSuccessToast(this.toastController);
                }
              },
              err => {
                SharedIonic.dismissLoading(this.loadingController);
                SharedIonic.unSuccessToast(this.toastController);
              }
            );
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  goPreviousPage() {

    if (this.filteredArticles.startPage == null) {
      return;
    }
    if (this.filteredArticles.pageId > this.filteredArticles.startPage && +this.filteredArticles.pageId - 1 > 0) {
      this.setQueryParams(+this.filteredArticles.pageId - 1);
    }
  }

  goNextPage() {

    if (this.filteredArticles.endPage == null) {
      return;
    }
    if (this.filteredArticles.pageId < this.filteredArticles.endPage) {
      this.setQueryParams(+this.filteredArticles.pageId + 1);
    }
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }

  setQueryParams(pageId: number) {

    this.filteredArticles.title = this.searchTitle;

    this.router
      .navigate(
        ['SellerPanel', 'UpdateArticle'],
        {
          queryParams:
          {
            page: pageId < 1 ? 1 : pageId,
            take: this.filteredArticles.takeEntity ? this.filteredArticles.takeEntity : null,
            title: this.filteredArticles.title ? this.filteredArticles.title : null
          }
        });
  }

  onSelectItem(model: IArticleModel) {

    this.selectedArticleId = +model.id;

    SharedIonic.loading(this.loadingController);

    this.articleService.GetProductArticleEditById(+model.id).subscribe(

      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {
          this.articleDetail = res.data;
          this.updateArticleForm.setValue({
            name: res.data.name,
            imageUrl: 'http://localhost:4300/assets/images/in-progress.webp',
            imageNamePNG: 'http://localhost:4300/assets/images/in-progress.png',
            shortDescriptionHtmlContent: res.data.shortDescription,
            descriptionHtmlContent: res.data.description
          });
          this.articleSelected = true;
        } else {
          SharedIonic.unSuccessToast(this.toastController);
          this.selectedArticleId = 0;
          this.articleSelected = false;
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
        this.selectedArticleId = 0;
        this.articleSelected = false;
      }
    );
  }

  onCancel() {

    this.selectedArticleId = 0;
    this.articleSelected = false;
  }
}
